const IOS_LOOKUP_COUNTRIES = ['hk', 'cn', 'us'] as const;

const PLAY_STORE_HEADERS = {
  'User-Agent':
    'Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36',
  'Accept-Language': 'en-US,en;q=0.9',
};

const STORE_LOOKUP_TIMEOUT_MS = 12000;

export interface StoreLookupResponse {
  ok: boolean;
  status?: number;
  json: () => Promise<unknown>;
  text: () => Promise<string>;
}

export type StoreLookupFetch = (
  url: string,
  init?: {headers?: Record<string, string>; signal?: AbortSignal},
) => Promise<StoreLookupResponse>;

const parseVersionParts = (version: string): number[] =>
  String(version ?? '')
    .split('.')
    .map(part => {
      const parsed = parseInt(part, 10);
      return Number.isFinite(parsed) ? parsed : 0;
    });

export const compareVersions = (left: string, right: string): number => {
  const leftParts = parseVersionParts(left);
  const rightParts = parseVersionParts(right);
  const length = Math.max(leftParts.length, rightParts.length);

  for (let index = 0; index < length; index += 1) {
    const leftPart = leftParts[index] ?? 0;
    const rightPart = rightParts[index] ?? 0;
    if (leftPart > rightPart) {
      return 1;
    }
    if (leftPart < rightPart) {
      return -1;
    }
  }

  return 0;
};

export const isStoreVersionNewer = (
  installedVersion: string,
  storeVersion: string | null,
): boolean => {
  if (!storeVersion?.trim()) {
    return false;
  }
  return compareVersions(storeVersion.trim(), installedVersion) > 0;
};

export const parseIosStoreVersion = (payload: unknown): string | null => {
  const results = (payload as {results?: Array<{version?: unknown}>} | null)
    ?.results;
  const version = results?.[0]?.version;
  return typeof version === 'string' && version.trim() ? version.trim() : null;
};

/** Play Store has no public version API. The listing page embeds the current version here. */
export const parseAndroidStoreVersion = (html: string): string | null => {
  const match = html.match(/"141":\[\[\["(\d+(?:\.\d+){1,3})"\]\]/);
  return match?.[1] ?? null;
};

export const resolveIosAppStoreId = (bundleId: string): string =>
  IOS_APP_STORE_IDS[bundleId] ??
  (bundleId.endsWith('.dev') ? '6740129703' : '6544800416');

export const getIosLookupUrls = (bundleId: string): string[] => {
  const appId = resolveIosAppStoreId(bundleId);
  return IOS_LOOKUP_COUNTRIES.map(
    country => `https://itunes.apple.com/lookup?id=${appId}&country=${country}`,
  );
};

export const getAndroidListingUrl = (bundleId: string): string =>
  `https://play.google.com/store/apps/details?id=${encodeURIComponent(bundleId)}&hl=en&gl=us`;

export const getIosStoreUrl = (bundleId: string): string =>
  `itms-apps://apps.apple.com/app/id${resolveIosAppStoreId(bundleId)}`;

export const getIosStoreWebUrl = (bundleId: string): string =>
  `https://apps.apple.com/app/id${resolveIosAppStoreId(bundleId)}`;

export const getAndroidStoreUrl = (bundleId: string): string =>
  `market://details?id=${bundleId}`;

export const getAndroidStoreWebUrl = (bundleId: string): string =>
  `https://play.google.com/store/apps/details?id=${bundleId}`;

const withTimeout = async <T>(work: (signal: AbortSignal) => Promise<T>): Promise<T> => {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), STORE_LOOKUP_TIMEOUT_MS);
  try {
    return await work(controller.signal);
  } finally {
    clearTimeout(timer);
  }
};

export const lookupStoreVersion = async (
  platform: 'ios' | 'android',
  bundleId: string,
  fetchImpl: StoreLookupFetch = fetch,
): Promise<string | null> => {
  if (platform === 'ios') {
    for (const url of getIosLookupUrls(bundleId)) {
      const version = await withTimeout(async signal => {
        const response = await fetchImpl(url, {signal});
        if (!response.ok) {
          return null;
        }
        return parseIosStoreVersion(await response.json());
      });
      if (version) {
        return version;
      }
    }
    return null;
  }

  return withTimeout(async signal => {
    const response = await fetchImpl(getAndroidListingUrl(bundleId), {
      headers: PLAY_STORE_HEADERS,
      signal,
    });
    if (!response.ok) {
      return null;
    }
    return parseAndroidStoreVersion(await response.text());
  });
};

import {
  compareVersions,
  getAndroidListingUrl,
  getIosLookupUrls,
  isStoreVersionNewer,
  lookupStoreVersion,
  parseAndroidStoreVersion,
  parseIosStoreVersion,
} from '../src/helper/app-update-policy';
import type {StoreLookupResponse} from '../src/helper/app-update-policy';

const jsonResponse = (body: unknown, ok = true): StoreLookupResponse => ({
  ok,
  status: ok ? 200 : 404,
  json: async () => body,
  text: async () => JSON.stringify(body),
});

const textResponse = (body: string, ok = true): StoreLookupResponse => ({
  ok,
  status: ok ? 200 : 404,
  json: async () => ({}),
  text: async () => body,
});

describe('store version lookup', () => {
  test('compares dotted versions numerically', () => {
    expect(compareVersions('1.2.3', '1.2.2')).toBe(1);
    expect(compareVersions('1.2.2', '1.2.2')).toBe(0);
    expect(compareVersions('1.2.1', '1.2.2')).toBe(-1);
    expect(compareVersions('1.2.10', '1.2.2')).toBe(1);
  });

  test('forces an update only when the store version is higher', () => {
    expect(isStoreVersionNewer('1.2.2', '1.2.3')).toBe(true);
    expect(isStoreVersionNewer('1.2.2', '1.2.2')).toBe(false);
    expect(isStoreVersionNewer('1.2.2', '1.2.1')).toBe(false);
    expect(isStoreVersionNewer('1.2.2', null)).toBe(false);
    expect(isStoreVersionNewer('1.2.2', '  ')).toBe(false);
  });

  test('reads the App Store lookup version', () => {
    expect(
      parseIosStoreVersion({
        resultCount: 1,
        results: [{version: '1.2.1', bundleId: 'com.healshealthcare.healspass'}],
      }),
    ).toBe('1.2.1');
    expect(parseIosStoreVersion({resultCount: 0, results: []})).toBeNull();
    expect(getIosLookupUrls('com.healshealthcare.healspass')[0]).toBe(
      'https://itunes.apple.com/lookup?id=6544800416&country=hk',
    );
  });

  test('reads the Play Store listing version and ignores a missing listing', async () => {
    const html = '"141":[[["1.2.1"]],[[[36]]';
    expect(parseAndroidStoreVersion(html)).toBe('1.2.1');
    expect(parseAndroidStoreVersion('<html>no version</html>')).toBeNull();
    expect(getAndroidListingUrl('com.healshealthcare.healspass')).toContain(
      'id=com.healshealthcare.healspass',
    );

    const version = await lookupStoreVersion(
      'android',
      'com.healshealthcare.healspass',
      async () => textResponse(html),
    );
    expect(version).toBe('1.2.1');

    const missing = await lookupStoreVersion(
      'android',
      'com.healshealthcare.healspass.dev',
      async () => textResponse('missing', false),
    );
    expect(missing).toBeNull();
  });

  test('uses the first App Store country that returns a version', async () => {
    const calls: string[] = [];
    const version = await lookupStoreVersion(
      'ios',
      'com.healshealthcare.healspass',
      async url => {
        calls.push(url);
        if (url.includes('country=hk')) {
          return jsonResponse({resultCount: 0, results: []});
        }
        return jsonResponse({
          resultCount: 1,
          results: [{version: '1.2.3'}],
        });
      },
    );

    expect(version).toBe('1.2.3');
    expect(calls[0]).toContain('country=hk');
    expect(calls[1]).toContain('country=cn');
  });
});

