import React, {useEffect, useRef, useState, memo, useCallback} from 'react'
import {
  Platform,
  Linking,
  AppState, AppStateStatus,
  BackHandler,
} from 'react-native'
import {
  isPaymentDocumentUrl,
  isPaymentExitUrl,
} from './payment-exit-url';
import {ProductWaitingRoomProps} from "@screens/product-waiting-room/product-waiting-room.props.ts";
import {ThemeContext} from "@style/theme/theme-context.tsx";
import type {Theme} from "@types/Theme.ts";
import NavigationBar from "@components/navigation-bar/navigation-bar.tsx";
import PageRightBt from "@components/page-right-bt/page-right-bt.tsx";
import {PurchaseRecord} from "@api/api-types.ts";
import type {Policys} from "@api/api-types.ts";
import WebViewComp from "@components/webView-comp/webView-comp.tsx";
import {useLoading} from "@components/loading-modal/loading-context.tsx";
import {WebViewNavigation} from 'react-native-webview';
import {WebViewNativeEvent} from 'react-native-webview/src/WebViewTypes.ts';
import {CommonActions} from '@react-navigation/native';
import {
  FAKE_PENDING_TRANSACTION,
  isFakePendingTransaction,
} from '../../constants/fake-transactions.ts';
import FakeTransactionProcessing from './fake-transaction-processing.tsx';
import {useAppState} from '@store/AppContext.tsx';
import {
  fetchSelectableBenefitPlans,
  selectPurchasedConsultPolicy,
} from '@services/benefit-plan-service';

export const shouldResumeDoctorDetailAfterPayment = (
  isSettled: boolean,
  resumeDoctorDetailPlanId?: string,
): boolean => isSettled && Boolean(resumeDoctorDetailPlanId);

const readRecommendedPlanId = (
  navigation: ProductWaitingRoomProps['navigation'] | undefined,
): string | undefined => {
  const navigationState = navigation?.getState?.();
  const previousRoute = navigationState?.routes[navigationState.index - 1];

  if (!previousRoute || previousRoute.name !== $routeNames.doctorDetailScreen) {
    return undefined;
  }

  const params = previousRoute.params as {
    recommendedGpQuery?: {
      planId?: string;
    };
  } | undefined;

  return params?.recommendedGpQuery?.planId;
};

const readPreviousDoctorDetailRouteKey = (
  navigation: ProductWaitingRoomProps['navigation'] | undefined,
): string | undefined => {
  const navigationState = navigation?.getState?.();
  const previousRoute = navigationState?.routes[navigationState.index - 1];

  return previousRoute?.name === $routeNames.doctorDetailScreen
    ? previousRoute.key
    : undefined;
};

const readCurrentRouteKey = (
  navigation: ProductWaitingRoomProps['navigation'] | undefined,
): string | undefined => {
  const navigationState = navigation?.getState?.();

  return navigationState?.routes[navigationState.index]?.key;
};

interface StateProps {
  isSettled?: boolean,
  payUrl: string
}

const ProductWaitingRoomScreen: React.FC<ProductWaitingRoomProps> = (props: ProductWaitingRoomProps, parentRef) => {
  const {} = props
  const {
    autoBookAfterPayment = false,
    id,
    payUrl,
    shouldPollForSettlement = true,
    resumeDoctorDetailPlanId,
  } = $getPageParams(props) as {
    autoBookAfterPayment?: boolean,
    id: string,
    payUrl: string,
    shouldPollForSettlement?: boolean,
    resumeDoctorDetailPlanId?: string,
  }
  const {setPlan, setSelectedPolicies} = useAppState();
  const {setLoading, setLoadingText} = useLoading();
  const isSettledRef = useRef(false);
  const allowLeaveRef = useRef(false);
  const leavingRef = useRef(false);
  const resumePlanIdRef = useRef<string | undefined>(undefined);
  resumePlanIdRef.current = resumeDoctorDetailPlanId ?? readRecommendedPlanId(props.navigation);
  const isFakeTransaction = $fake && isFakePendingTransaction(id);
  const canPollForSettlement = shouldPollForSettlement && !isFakeTransaction;
  const canPollRef = useRef(canPollForSettlement);
  canPollRef.current = canPollForSettlement;
  const loadingVisibleRef = useRef(false);
  const [state, setState] = useState<StateProps>({
    isSettled: false, payUrl: payUrl
  })
  isSettledRef.current = state.isSettled === true;

  const selectPurchasedPlan = useCallback(async (): Promise<Policys | undefined> => {
    const planId = resumePlanIdRef.current;

    if (!planId) {
      return undefined;
    }

    const readPolicy = async (): Promise<Policys | undefined> => {
      const policies = await fetchSelectableBenefitPlans();

      return selectPurchasedConsultPolicy(policies, planId);
    };

    let selectedPolicy = await readPolicy();

    if (!selectedPolicy) {
      await new Promise<void>((resolve: () => void): void => {
        setTimeout(resolve, 800);
      });
      selectedPolicy = await readPolicy();
    }

    if (selectedPolicy) {
      setPlan(selectedPolicy.plan);
      setSelectedPolicies(selectedPolicy);
    }

    return selectedPolicy;
  }, [setPlan, setSelectedPolicies]);

  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const requestInFlightRef = useRef(false);
  const settledRef = useRef(false);
  const openedPaymentRef = useRef(false);
  const closeRequestedRef = useRef(false);
  const leftToPlansRef = useRef(false);
  const appState = useRef(AppState.currentState);
  const ref_url = useRef<string>('');
  const webViewRef = useRef(null);
  const purchaseIdRef = useRef(id);
  purchaseIdRef.current = id;

  const clearSettlementPoll = () => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
  };

  const leaveAfterSettledPayment = (): void => {
    if (!settledRef.current || leftToPlansRef.current) {
      return;
    }
    leftToPlansRef.current = true;
    clearSettlementPoll();
    if (shouldResumeDoctorDetailAfterPayment(true, resumePlanIdRef.current)) {
      $NavigationActions.goBack();
      return;
    }
    $NavigationActions.replace($routeNames.mainTabNavigator);
    $NavigationActions.replace($routeNames.healsPlanScreen);
  };

  const rememberPaymentUrl = (url?: string | null): void => {
    if (!url) {
      return;
    }
    ref_url.current = url;
    if (isPaymentDocumentUrl(url)) {
      openedPaymentRef.current = true;
    }
  };

  // Close and the header back both end on the purchased-plan list once the
  // gateway has settled. A consult checkout instead returns to doctor detail.
  const requestLeaveAfterPayment = (url?: string | null): boolean => {
    rememberPaymentUrl(url);
    if (!openedPaymentRef.current || !isPaymentExitUrl(url)) {
      return false;
    }
    closeRequestedRef.current = true;
    if (settledRef.current) {
      leaveAfterSettledPayment();
    }
    return true;
  };

  const finishHPPurchase = useCallback(() => {
    const purchaseId = purchaseIdRef.current;
    if (
      !canPollRef.current ||
      !purchaseId ||
      settledRef.current ||
      requestInFlightRef.current
    ) {
      return;
    }

    clearSettlementPoll();
    requestInFlightRef.current = true;
    void (async () => {
      try {
        const res: PurchaseRecord = await $api.finishHPPurchase(purchaseId);
        console.log('finishHPPurchase res', res);
        console.log('finishHPPurchase id', purchaseId);
        if (res?.isSettled) {
          settledRef.current = true;
          isSettledRef.current = true;
          setState(prevState => {
            return {
              ...prevState,
              isSettled: true,
            };
          });
          if (closeRequestedRef.current || isPaymentExitUrl(ref_url.current)) {
            leaveAfterSettledPayment();
          }
          return;
        }
      } catch {
        // 400 means the purchase is not settled yet. Keep polling quietly.
      } finally {
        requestInFlightRef.current = false;
      }

      if (!settledRef.current && appState.current === 'active') {
        timeoutRef.current = setTimeout(() => {
          finishHPPurchase();
        }, 5000);
      }
    })();
  }, []);

  const hidePageLoading = useCallback(() => {
    if (!loadingVisibleRef.current) {
      return;
    }
    loadingVisibleRef.current = false;
    setLoading(false);
  }, [setLoading]);

  const handleWebViewLoadEnd = useCallback((navState: WebViewNativeEvent) => {
    if (requestLeaveAfterPayment(navState.url)) {
      return;
    }
    if (!navState.url || isPaymentExitUrl(navState.url)) {
      return;
    }
    hidePageLoading();
  }, [hidePageLoading]);

  const handleHeaderBack = (): void => {
    if (settledRef.current) {
      leaveAfterSettledPayment();
      return;
    }
    $NavigationActions.goBack();
  };

  useEffect(() => {
    const subscription = BackHandler.addEventListener('hardwareBackPress', () => {
      if (!settledRef.current) {
        return false;
      }
      leaveAfterSettledPayment();
      return true;
    });
    return () => subscription.remove();
  }, []);

  useEffect(() => {
    if (isFakeTransaction) {
      return undefined;
    }
    loadingVisibleRef.current = true;
    setLoadingText($i18n.t('loading'));
    setLoading(true);
    return () => {
      loadingVisibleRef.current = false;
      setLoading(false);
    };
  }, [isFakeTransaction, setLoading, setLoadingText]);

  useEffect(
    () => {
      if (!canPollForSettlement) {
        return undefined;
      }
      finishHPPurchase();
      const handleAppStateChange = (nextAppState: AppStateStatus) => {
        if (appState.current.match(/active/) && nextAppState === 'background') {
          clearSettlementPoll();
        } else if (nextAppState === 'active' && !settledRef.current) {
          setState(prevState => {
            return {
              ...prevState,
              payUrl,
            };
          });
          finishHPPurchase();
        }
        appState.current = nextAppState;
      };
      const subscription = AppState.addEventListener('change', handleAppStateChange);
      return () => {
        subscription.remove();
        clearSettlementPoll();
      };
    }, [canPollForSettlement, finishHPPurchase, payUrl])
  useEffect(() => {
    const navigation = props.navigation;

    if (!navigation?.addListener) {
      return undefined;
    }

    const unsubscribe = navigation.addListener('beforeRemove', (event) => {
      if (
        allowLeaveRef.current ||
        event.data.action.type !== 'GO_BACK' ||
        !shouldResumeDoctorDetailAfterPayment(
          isSettledRef.current,
          resumePlanIdRef.current,
        )
      ) {
        return;
      }

      event.preventDefault();

      if (leavingRef.current) {
        return;
      }

      leavingRef.current = true;

      const leaveAfterSelectingPlan = async (): Promise<void> => {
        if (autoBookAfterPayment) {
          setLoading(true);
        }

        try {
          const selectedPolicy = await selectPurchasedPlan();
          const doctorDetailRouteKey = readPreviousDoctorDetailRouteKey(navigation);
          const waitingRoomRouteKey = readCurrentRouteKey(navigation);

          if (
            autoBookAfterPayment &&
            selectedPolicy &&
            doctorDetailRouteKey &&
            waitingRoomRouteKey
          ) {
            // Doctor detail books and replaces this route, so it never shows.
            navigation.dispatch({
              ...CommonActions.setParams({
                autoBookPolicyId: selectedPolicy.id,
                autoBookReplaceRouteKey: waitingRoomRouteKey,
              }),
              source: doctorDetailRouteKey,
            });
            return;
          }
        } catch (error) {
          console.log(
            'Exception encountered @ ProductWaitingRoom.resumeDoctorDetail',
            error,
          );
        }

        if (autoBookAfterPayment) {
          setLoading(false);
        }

        allowLeaveRef.current = true;
        navigation.dispatch(event.data.action);
      };

      leaveAfterSelectingPlan().then();
    });

    return unsubscribe;
  }, [autoBookAfterPayment, props.navigation, selectPurchasedPlan, setLoading]);
  if (isFakeTransaction) {
    return (
      <>
        <NavigationBar
          title={$i18n.t('tx_processing')}
          rightBt={<PageRightBt tag={$routeNames.productWaitingRoom} />}
        />
        <FakeTransactionProcessing transaction={FAKE_PENDING_TRANSACTION} />
      </>
    );
  }
  //render
  return (
    <ThemeContext.Consumer>
      {(theme: Theme) => {
        return (
          <>
            <NavigationBar
              title={$i18n.t('tx_processing')}
              onLeftPress={handleHeaderBack}
              rightBt={<PageRightBt tag={$routeNames.productWaitingRoom} />}
            />
            <WebViewComp
              ref={webViewRef}
              source={{uri: state.payUrl}}
              onLoadEnd={handleWebViewLoadEnd}
              onNavigationChange={(navState: WebViewNavigation) => {
                requestLeaveAfterPayment(navState.url);
              }}
              onShouldStartLoadWithRequest={(request: WebViewNavigation) => {
                const url = request?.url;
                if (requestLeaveAfterPayment(url)) {
                  return false;
                }
                if (!url) {
                  return true;
                }
                if (url.includes('mclient.alipay.com')) {
                  webViewRef.current?.reload();
                  Linking.openURL(url)
                    .then(() => {
                    })
                    .catch((err) => {
                    });
                  return false;
                }
                if (url.startsWith('weixin://') || url.startsWith('alipays://') || url.startsWith('alipayhk://')) {
                  Linking.openURL(url)
                    .then(() => {
                    })
                    .catch((err) => {
                      if (url.startsWith('weixin://')) {
                        let downloadUrl = ''
                        if ($i18n.locale === 'zh-Hans') {
                          downloadUrl = Platform.OS === 'ios'
                            ? 'https://apps.apple.com/cn/app/wechat/id414478124'
                            : 'https://play.google.com/store/apps/details?id=com.tencent.mm';
                        } else if ($i18n.locale === 'zh-Hant') {
                          downloadUrl = Platform.OS === 'ios'
                            ? 'https://apps.apple.com/hk/app/wechat/id414478124'
                            : 'https://play.google.com/store/apps/details?id=com.tencent.mm';
                        } else {
                          downloadUrl = Platform.OS === 'ios'
                            ? 'https://apps.apple.com/us/app/wechat/id414478124'
                            : 'https://play.google.com/store/apps/details?id=com.tencent.mm';
                        }
                        Linking.openURL(downloadUrl);
                      }
                    });
                  return false;
                }
                return true;
              }
              }
            />
          </>
        );
      }}
    </ThemeContext.Consumer>
  )
}
export default memo(ProductWaitingRoomScreen);

