// Usage: node /tmp/ts-diag.js <projectRoot> <fileListPath> <outJson>
const fs = require('fs');
const path = require('path');

const [projectRoot, fileListPath, outPath] = process.argv.slice(2);
const ts = require(path.join(projectRoot, 'node_modules/typescript'));

const configPath = path.join(projectRoot, 'tsconfig.json');
const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(
  configFile.config,
  ts.sys,
  projectRoot,
);

const changed = fs
  .readFileSync(fileListPath, 'utf8')
  .split('\n')
  .map(line => line.trim())
  .filter(Boolean)
  .map(rel => path.join(projectRoot, rel))
  .filter(abs => fs.existsSync(abs));

const rootNames = Array.from(new Set([...parsed.fileNames, ...changed]));
const versions = new Map(rootNames.map(name => [name, '1']));

const host = {
  getScriptFileNames: () => rootNames,
  getScriptVersion: name => versions.get(name) ?? '1',
  getScriptSnapshot: name =>
    fs.existsSync(name)
      ? ts.ScriptSnapshot.fromString(fs.readFileSync(name, 'utf8'))
      : undefined,
  getCurrentDirectory: () => projectRoot,
  getCompilationSettings: () => parsed.options,
  getDefaultLibFileName: options => ts.getDefaultLibFilePath(options),
  fileExists: ts.sys.fileExists,
  readFile: ts.sys.readFile,
  readDirectory: ts.sys.readDirectory,
  directoryExists: ts.sys.directoryExists,
  getDirectories: ts.sys.getDirectories,
};

const service = ts.createLanguageService(host, ts.createDocumentRegistry());
const results = [];

const pushDiagnostic = (kind, file, diagnostic) => {
  const rel = path.relative(projectRoot, file);
  let line = 0;
  let text = '';
  if (diagnostic.file && typeof diagnostic.start === 'number') {
    const pos = diagnostic.file.getLineAndCharacterOfPosition(diagnostic.start);
    line = pos.line + 1;
    const lineText = diagnostic.file.text.split('\n')[pos.line] ?? '';
    text = lineText.trim().slice(0, 160);
  }
  results.push({
    kind,
    file: rel,
    line,
    code: diagnostic.code,
    message: ts.flattenDiagnosticMessageText(diagnostic.messageText, '\n'),
    text,
  });
};

for (const file of changed) {
  service.getSyntacticDiagnostics(file).forEach(d => pushDiagnostic('syntactic', file, d));
  service.getSemanticDiagnostics(file).forEach(d => pushDiagnostic('semantic', file, d));
  service.getSuggestionDiagnostics(file).forEach(d => pushDiagnostic('suggestion', file, d));
}

fs.writeFileSync(outPath, JSON.stringify(results, null, 2));
const counts = {};
results.forEach(r => {
  counts[r.kind] = (counts[r.kind] ?? 0) + 1;
});
console.log(`files=${changed.length} roots=${rootNames.length}`, counts);

