// Usage: node /tmp/ts-contract.js <projectRoot> <baseRef>
// Reports named functions whose declaration line is added in baseRef..HEAD
// and that lack explicit parameter or return types, plus added `any`.
const {execSync} = require('child_process');
const fs = require('fs');
const path = require('path');

const [projectRoot, baseRef] = process.argv.slice(2);
const ts = require(path.join(projectRoot, 'node_modules/typescript'));

const files = execSync(
  `git diff --name-only --diff-filter=AMR ${baseRef} HEAD -- '*.ts' '*.tsx'`,
  {cwd: projectRoot, encoding: 'utf8'},
)
  .split('\n')
  .map(line => line.trim())
  .filter(Boolean);

const addedLines = file => {
  const diff = execSync(`git diff -U0 ${baseRef} HEAD -- '${file}'`, {
    cwd: projectRoot,
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });
  const lines = new Set();
  let current = 0;
  diff.split('\n').forEach(line => {
    const hunk = line.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/);
    if (hunk) {
      current = Number(hunk[1]);
      return;
    }
    if (line.startsWith('+') && !line.startsWith('+++')) {
      lines.add(current);
      current += 1;
    } else if (!line.startsWith('-')) {
      current += 1;
    }
  });
  return lines;
};

const isFunctionLike = node =>
  ts.isArrowFunction(node) || ts.isFunctionExpression(node);

const unwrapHookCallback = node => {
  if (
    node &&
    ts.isCallExpression(node) &&
    ts.isIdentifier(node.expression) &&
    ['useCallback', 'useMemo'].includes(node.expression.text) &&
    node.arguments.length > 0 &&
    isFunctionLike(node.arguments[0])
  ) {
    return node.arguments[0];
  }
  return undefined;
};

const report = [];

files.forEach(file => {
  const abs = path.join(projectRoot, file);
  if (!fs.existsSync(abs)) {
    return;
  }
  const added = addedLines(file);
  const text = fs.readFileSync(abs, 'utf8');
  const source = ts.createSourceFile(
    abs,
    text,
    ts.ScriptTarget.Latest,
    true,
    file.endsWith('.tsx') ? ts.ScriptKind.TSX : ts.ScriptKind.TS,
  );
  const lineOf = node =>
    source.getLineAndCharacterOfPosition(node.getStart(source)).line + 1;

  const checkFn = (name, fn, declNode, hasDeclaredType) => {
    const line = lineOf(declNode);
    if (!added.has(line)) {
      return;
    }
    const problems = [];
    fn.parameters.forEach(param => {
      if (!param.type && !param.initializer) {
        problems.push(`param ${param.name.getText(source)} untyped`);
      }
    });
    if (!fn.type && !hasDeclaredType) {
      problems.push('no return type');
    }
    if (problems.length > 0) {
      report.push(`${file}:${line} ${name}: ${problems.join(', ')}`);
    }
  };

  const visit = node => {
    if (ts.isFunctionDeclaration(node) && node.name) {
      checkFn(node.name.text, node, node, false);
    }
    if (ts.isVariableDeclaration(node) && ts.isIdentifier(node.name) && node.initializer) {
      const fn = isFunctionLike(node.initializer)
        ? node.initializer
        : unwrapHookCallback(node.initializer);
      if (fn) {
        checkFn(node.name.text, fn, node, Boolean(node.type));
      }
    }
    if (node.kind === ts.SyntaxKind.AnyKeyword && added.has(lineOf(node))) {
      report.push(`${file}:${lineOf(node)} any: ${node.parent.getText(source).slice(0, 100)}`);
    }
    ts.forEachChild(node, visit);
  };
  visit(source);
});

console.log(report.join('\n') || 'no violations');

