import type {Plan, Policys} from '@api/api-types.ts';

/** The ticket's payorId must belong to the policy sent as insurancePolicyId. */
export const resolveTicketPayorId = (
  selectedPolicy: Pick<Policys, 'plan'> | null | undefined,
  plan: Pick<Plan, 'payorId'> | null | undefined,
): string => selectedPolicy?.plan?.payorId || plan?.payorId || '';

import {resolveTicketPayorId} from '../src/screens/doctor-detail-screen/doctor-ticket-payor';

const helperTrialPolicy = {
  plan: {
    id: '6e931304-a037-4aee-bf7c-1d495422f7fc',
    name: 'Helper Trial',
    isProduct: true,
    providerCountries: [],
    payorId: '34436649-d000-41b0-947e-356190ce5cdf',
  },
};

describe('resolveTicketPayorId', () => {
  test('uses the selected policy payor when Doctor List left the global plan empty', () => {
    expect(resolveTicketPayorId(helperTrialPolicy, null)).toBe(
      '34436649-d000-41b0-947e-356190ce5cdf',
    );
  });

  test('prefers the selected policy payor over a stale global plan', () => {
    expect(
      resolveTicketPayorId(helperTrialPolicy, {payorId: 'stale-payor-id'}),
    ).toBe('34436649-d000-41b0-947e-356190ce5cdf');
  });

  test('falls back to the global plan payor when no policy is selected', () => {
    expect(resolveTicketPayorId(undefined, {payorId: 'plan-payor-id'})).toBe(
      'plan-payor-id',
    );
  });

  test('returns an empty string only when neither source has a payor', () => {
    expect(resolveTicketPayorId(null, null)).toBe('');
  });
});

